using Microsoft.AspNetCore.Mvc;
using RaceDay.Mvc.Models;
using RaceDay.Mvc.Services;
using System.Text.Json;

namespace RaceDay.Mvc.Controllers;
public sealed class OrganiserController:BaseController
{
 public OrganiserController(RaceDayApiClient api):base(api){}
 public async Task<IActionResult> Dashboard(){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Get,"api/events");if(!res.IsSuccessStatusCode){TempData["Error"]=await RaceDayApiClient.ErrorAsync(res);return View(new OrganiserDashboardViewModel());}var data=await RaceDayApiClient.ReadAsync<JsonElement>(res);var model=new OrganiserDashboardViewModel();if(data.ValueKind==JsonValueKind.Array){foreach(var e in data.EnumerateArray().Where(x=>x.GetProperty("organiserID").GetInt32()==HttpContext.Session.GetInt32("UserId"))){var id=e.GetProperty("eventID").GetInt32();var item=new EventDashboardItem{EventID=id,EventName=e.GetProperty("eventName").GetString()??"",EventDate=e.GetProperty("eventDate").GetDateTime(),Location=e.GetProperty("location").GetString()??"",Distance=e.GetProperty("distance").GetDecimal()};using var enrolments=await Api.SendAsync(HttpMethod.Get,$"api/events/{id}/enrolments");if(enrolments.IsSuccessStatusCode){var entries=await RaceDayApiClient.ReadAsync<JsonElement>(enrolments);if(entries.ValueKind==JsonValueKind.Array)item.EnrolmentCount=entries.GetArrayLength();}model.Events.Add(item);}}return View(model);}
 public async Task<IActionResult> Events(){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Get,"api/events");return View(new ApiPageViewModel{Data=await RaceDayApiClient.ReadAsync<JsonElement>(res)});}
 [HttpGet] public IActionResult CreateEvent(){if(RequireRole("Organiser") is IActionResult r)return r;return View("EventForm",new EventFormViewModel());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CreateEvent(EventFormViewModel model){if(RequireRole("Organiser") is IActionResult r)return r;if(!ModelState.IsValid)return View("EventForm",model);using var res=await Api.SendAsync(HttpMethod.Post,"api/events",new{model.EventName,model.Description,model.EventDate,model.Location,model.Distance,model.EventType,model.RouteID,BannerImageUrl=(string?)null});if(!res.IsSuccessStatusCode){ModelState.AddModelError("",await RaceDayApiClient.ErrorAsync(res));return View("EventForm",model);}var created=await RaceDayApiClient.ReadAsync<JsonElement>(res);var id=created.GetProperty("eventID").GetInt32();if(model.Banner is not null){using var upload=await Api.SendFileAsync($"api/uploads/events/{id}/banner",model.Banner);if(!upload.IsSuccessStatusCode)TempData["Error"]=await RaceDayApiClient.ErrorAsync(upload);}TempData["Success"]="Event created.";return RedirectToAction(nameof(Events));}
 [HttpGet] public async Task<IActionResult> EditEvent(int id){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Get,$"api/events/{id}");if(!res.IsSuccessStatusCode)return RedirectToAction(nameof(Events));var e=await RaceDayApiClient.ReadAsync<JsonElement>(res);return View("EventForm",new EventFormViewModel{EventID=id,EventName=e.GetProperty("eventName").GetString()??"",Description=e.TryGetProperty("description",out var d)?d.GetString():null,EventDate=e.GetProperty("eventDate").GetDateTime(),Location=e.GetProperty("location").GetString()??"",Distance=e.GetProperty("distance").GetDecimal(),EventType=e.GetProperty("eventType").GetString()??"Run",RouteID=e.GetProperty("route").GetProperty("routeID").GetInt32(),BannerImageUrl=e.TryGetProperty("bannerImageUrl",out var b)?b.GetString():null});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> EditEvent(EventFormViewModel model){if(RequireRole("Organiser") is IActionResult r)return r;if(!ModelState.IsValid)return View("EventForm",model);using var res=await Api.SendAsync(HttpMethod.Put,$"api/events/{model.EventID}",new{model.EventName,model.Description,model.EventDate,model.Location,model.Distance,model.EventType,model.RouteID,model.BannerImageUrl});if(!res.IsSuccessStatusCode){ModelState.AddModelError("",await RaceDayApiClient.ErrorAsync(res));return View("EventForm",model);}if(model.Banner is not null){using var upload=await Api.SendFileAsync($"api/uploads/events/{model.EventID}/banner",model.Banner);if(!upload.IsSuccessStatusCode)TempData["Error"]=await RaceDayApiClient.ErrorAsync(upload);}TempData["Success"]="Event updated.";return RedirectToAction(nameof(Events));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteEvent(int id){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Delete,$"api/events/{id}");TempData[res.IsSuccessStatusCode?"Success":"Error"]=res.IsSuccessStatusCode?"Event deleted.":await RaceDayApiClient.ErrorAsync(res);return RedirectToAction(nameof(Events));}
 public async Task<IActionResult> Categories(int eventId){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Get,$"api/events/{eventId}/categories");return View(new ApiPageViewModel{Data=await RaceDayApiClient.ReadAsync<JsonElement>(res),Title=$"Categories · Event {eventId}"});}
 [HttpGet] public IActionResult AddCategory(int eventId){if(RequireRole("Organiser") is IActionResult r)return r;return View(new CategoryFormViewModel{EventId=eventId});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddCategory(CategoryFormViewModel m){if(RequireRole("Organiser") is IActionResult r)return r;if(!ModelState.IsValid)return View(m);using var res=await Api.SendAsync(HttpMethod.Post,$"api/events/{m.EventId}/categories",new{m.CategoryName,m.MinAge,m.MaxAge});if(!res.IsSuccessStatusCode)ModelState.AddModelError("",await RaceDayApiClient.ErrorAsync(res));else TempData["Success"]="Category added.";return ModelState.IsValid?RedirectToAction(nameof(Categories),new{eventId=m.EventId}):View(m);}
 public async Task<IActionResult> Enrolments(int eventId){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Get,$"api/events/{eventId}/enrolments");return View(new ApiPageViewModel{Data=await RaceDayApiClient.ReadAsync<JsonElement>(res),Title=$"Enrolments · Event {eventId}"});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UpdateEnrolmentStatus(int id,int eventId,string status){if(RequireRole("Organiser") is IActionResult r)return r;using var res=await Api.SendAsync(HttpMethod.Put,$"api/enrolments/{id}/status",new{Status=status});TempData[res.IsSuccessStatusCode?"Success":"Error"]=res.IsSuccessStatusCode?"Enrolment status updated.":await RaceDayApiClient.ErrorAsync(res);return RedirectToAction(nameof(Enrolments),new{eventId});}
 [HttpGet] public IActionResult AddResult(int enrolmentId){if(RequireRole("Organiser") is IActionResult r)return r;return View(new ResultFormViewModel{EnrolmentID=enrolmentId});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddResult(ResultFormViewModel m){if(RequireRole("Organiser") is IActionResult r)return r;TimeSpan? time=TimeSpan.TryParse(m.FinishTime,out var t)?t:null;using var res=await Api.SendAsync(HttpMethod.Post,"api/results",new{m.EnrolmentID,FinishTime=time, m.FinishingPosition,m.ResultStatus});if(!res.IsSuccessStatusCode){ModelState.AddModelError("",await RaceDayApiClient.ErrorAsync(res));return View(m);}TempData["Success"]="Race result recorded.";return RedirectToAction(nameof(Events));}
}
